Object.assign(SNIP,{"l42cu": "//  [bắt]  (tham số)  -> kiểu trả về (thường bỏ)  { thân }\nauto binhPhuong = [](int x) { return x * x; };\ncout << binhPhuong(5);                       // 25: gọi như một hàm\n\nsort(v.begin(), v.end(), [](int a, int b) { return a > b; });   // viết ngay tại chỗ dùng", "l42bat": "int k = 10, dem = 0;\nauto f = [k](int x) { return x + k; };       // chép k vào lambda lúc tạo\nauto g = [&dem]() { dem++; };                // dùng chính biến dem\nauto h = [=](int x) { return x * k; };       // tự bắt (chép) mọi biến được dùng\nauto t = [&](int x) { dem += x; };           // tự bắt theo tham chiếu mọi biến được dùng", "l42fn": "#include <functional>\nfunction<int(int, int)> phep;                 // giữ được hàm, lambda… có dạng int(int, int)\nphep = [](int a, int b) { return a + b; };\nphep = nhan;                                  // nhan là hàm int nhan(int, int)\nvoid apDung(vector<int>& v, function<int(int)> g);   // tham số là một hàm"});PRESET_NOTES["l42"]={"Ví dụ: lambda đầu tiên": "binhPhuong là một biến giữ lambda; gọi nó như gọi hàm. Lambda thứ hai được viết ngay trong lời gọi sort: a > b nghĩa là số lớn đứng trước, nên dãy giảm dần.", "Ví dụ: bắt biến k cho count_if": "k nhập lúc chạy nên không viết sẵn được một hàm laLonHon5. [k] chép k vào lambda; count_if gọi lambda với từng phần tử. Ở Bộ nhớ, trong khung lambda, k hiện là “bản chép trong lambda”.", "Ví dụ: chép giá trị hay dùng chung biến": "chep giữ bản chép của a lúc tạo (1), nên sửa a sau đó không ảnh hưởng. chung dùng chính b nên thấy 100. tang sửa thẳng biến b của main.", "Ví dụ: mutable và bộ đếm riêng": "Bản chép dem nằm TRONG lambda và được giữ lại giữa các lần gọi, nên ra 1 2 3. mutable cho phép sửa bản chép đó (mặc định bản chép là hằng). Biến dem của main không đổi: vẫn là 0.", "Ví dụ: for_each cộng dồn bằng [&]": "[&] để lambda sửa thẳng tong và lonNhat của main. transform ghi kết quả của lambda đè lên chính v (đích là v.begin()).", "Ví dụ: sort theo nhiều tiêu chí": "Điểm cao đứng trước; cùng điểm thì tên theo thứ tự bảng chữ cái (Binh trước Chi). Tham số là const HocVien& để không phải chép cả struct mỗi lần so sánh.", "Ví dụ: std::function và hàm nhận hàm": "Cùng một biến phep lúc giữ lambda, lúc giữ hàm nhan: lời gọi phep(3, 4) cho 7 rồi 12. apDung không cần biết g là gì, chỉ cần g nhận int và trả về int.", "Lỗi: dùng biến chưa bắt": "[] rỗng nên thân lambda không thấy biến k của main. Sửa: [k] (chép) hoặc [&k] (dùng chung).", "Lỗi: sửa bản chép khi thiếu mutable": "Bản chép trong lambda mặc định là hằng. Muốn sửa bản chép: thêm mutable; muốn sửa biến dem của main: bắt [&dem].", "Lỗi: tham chiếu treo": "dem là biến cục bộ của taoBoDem: nó bị hủy khi hàm kết thúc, nhưng lambda trả về vẫn giữ tham chiếu tới nó. Gọi f() là dùng một biến đã chết (máy thật có thể in số rác hoặc dừng). Sửa: [dem]() mutable { return ++dem; } để lambda giữ bản chép của riêng nó."};EX_HINTS["l42"]=[["Lambda trả về true khi a phải đứng trước b.", "So sánh điểm trước (>), điểm bằng nhau mới so tên (<)."], ["a, b chỉ cần đọc nên bắt theo giá trị; tong phải được sửa nên bắt theo tham chiếu [&tong].", "Thiếu & thì lambda sửa bản chép (và báo lỗi vì bản chép là hằng)."], ["Mỗi giá trị của map là một function, gán bằng một lambda.", "bang[op] lấy ra function, (a, b) gọi nó."]];
/* ===================== BÀI 42 · Lambda ===================== */
/* Bài 42 · Lambda
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P42=[{label:"Ví dụ: lambda đầu tiên",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    auto binhPhuong = [](int x) { return x * x; };\n    cout << binhPhuong(5) << \"\\n\";\n    vector<int> v = {3, 9, 1, 7};\n    sort(v.begin(), v.end(), [](int a, int b) { return a > b; });\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:[]}]},{label:"Ví dụ: bắt biến k cho count_if",input:"5",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 12, 7, 15, 9, 20};\n    int k;\n    cin >> k;\n    int dem = count_if(v.begin(), v.end(), [k](int x) { return x > k; });\n    cout << \"Co \" << dem << \" so lon hon \" << k << \"\\n\";\n    auto it = find_if(v.begin(), v.end(), [k](int x) { return x % k == 0; });\n    if (it != v.end()) cout << \"So dau tien chia het cho \" << k << \": \" << *it << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:["it"]},{type:"mem"}]},{label:"Ví dụ: chép giá trị hay dùng chung biến",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a = 1, b = 1;\n    auto chep = [a]() { return a; };\n    auto chung = [&b]() { return b; };\n    a = 100;\n    b = 100;\n    cout << chep() << \" \" << chung() << \"\\n\";\n    auto tang = [&b]() { b++; };\n    tang();\n    tang();\n    cout << \"b = \" << b << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: mutable và bộ đếm riêng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int dem = 0;\n    auto demRieng = [dem]() mutable { dem++; return dem; };\n    cout << demRieng() << \" \";\n    cout << demRieng() << \" \";\n    cout << demRieng() << \"\\n\";\n    cout << \"dem cua main = \" << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: for_each cộng dồn bằng [&]",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 3, 8, 2};\n    int tong = 0, lonNhat = v[0];\n    for_each(v.begin(), v.end(), [&](int x) {\n        tong += x;\n        if (x > lonNhat) lonNhat = x;\n    });\n    cout << \"Tong \" << tong << \", lon nhat \" << lonNhat << \"\\n\";\n    transform(v.begin(), v.end(), v.begin(), [](int x) { return 2 * x; });\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:[]},{type:"mem"}]},{label:"Ví dụ: sort theo nhiều tiêu chí",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <string>\nusing namespace std;\n\nstruct HocVien {\n    string ten;\n    int diem;\n};\nint main() {\n    vector<HocVien> ds = {{\"Chi\", 8}, {\"An\", 9}, {\"Binh\", 8}, {\"Dung\", 7}};\n    sort(ds.begin(), ds.end(), [](const HocVien& a, const HocVien& b) {\n        if (a.diem != b.diem) return a.diem > b.diem;\n        return a.ten < b.ten;\n    });\n    for (const auto& h : ds) {\n        cout << h.ten << \" \" << h.diem << \"\\n\";\n    }\n    return 0;\n}"},{label:"Ví dụ: std::function và hàm nhận hàm",input:"",code:"#include <iostream>\n#include <vector>\n#include <functional>\nusing namespace std;\n\nint nhan(int a, int b) {\n    return a * b;\n}\nvoid apDung(vector<int>& v, function<int(int)> g) {\n    for (int& x : v) {\n        x = g(x);\n    }\n}\nint main() {\n    function<int(int, int)> phep = [](int a, int b) { return a + b; };\n    cout << phep(3, 4) << \"\\n\";\n    phep = nhan;\n    cout << phep(3, 4) << \"\\n\";\n    vector<int> v = {1, 2, 3};\n    int them = 10;\n    apDung(v, [them](int x) { return x + them; });\n    for (int x : v) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v",ptr:[]},{type:"mem"}]},{label:"Lỗi: dùng biến chưa bắt",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 12, 7};\n    int k = 5;\n    int dem = count_if(v.begin(), v.end(), [](int x) { return x > k; });\n    cout << dem << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: sửa bản chép khi thiếu mutable",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int dem = 0;\n    auto f = [dem]() { dem++; };\n    f();\n    return 0;\n}"},{label:"Lỗi: tham chiếu treo",input:"",code:"#include <iostream>\n#include <functional>\nusing namespace std;\n\nfunction<int()> taoBoDem() {\n    int dem = 0;\n    return [&dem]() { return ++dem; };\n}\nint main() {\n    function<int()> f = taoBoDem();\n    cout << f() << \"\\n\";\n    return 0;\n}"}];
const sim42=makeSim2(document.getElementById("sim-l42"),{id:"s42",presets:P42});
makeEx2(document.getElementById("ex-l42"),sim42,[{t:"Bảng xếp hạng",d:"Nhập n rồi n dòng, mỗi dòng tên (không dấu cách) và điểm (số nguyên). In danh sách theo điểm giảm dần; cùng điểm thì tên theo thứ tự bảng chữ cái, mỗi dòng <code>hang. ten diem<\/code> (hạng bắt đầu từ 1, đánh số liên tiếp). Dùng <code>sort<\/code> với một lambda so sánh.",tests:[{in:"4\nChi 8\nAn 9\nBinh 8\nDung 7",out:"1. An 9\n2. Binh 8\n3. Chi 8\n4. Dung 7"},{in:"1\nTu 5",out:"1. Tu 5"},{in:"3\nc 1\nb 1\na 1",out:"1. a 1\n2. b 1\n3. c 1"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <string>\nusing namespace std;\n\nstruct HV {\n    string ten;\n    int diem;\n};\nint main() {\n    int n;\n    cin >> n;\n    vector<HV> ds(n);\n    for (auto& h : ds) cin >> h.ten >> h.diem;\n    // sort(ds.begin(), ds.end(), [](const HV& a, const HV& b) { ... });\n    for (int i = 0; i < n; i++) {\n        cout << i + 1 << \". \" << ds[i].ten << \" \" << ds[i].diem << \"\\n\";\n    }\n    return 0;\n}",need:/sort\s*\([^;]*\[/,needMsg:"Hãy truyền một lambda cho sort."},{t:"Đếm số trong khoảng",d:"Nhập n rồi n số nguyên, tiếp theo hai số a ≤ b. In số phần tử x thỏa a ≤ x ≤ b, và dòng thứ hai in tổng của chúng. Dùng <code>count_if<\/code> với lambda bắt a, b; tính tổng bằng <code>for_each<\/code> với lambda bắt biến tổng theo tham chiếu.",tests:[{in:"6\n4 -2 7 10 5 3\n3 7",out:"4\n19"},{in:"3\n1 2 3\n5 9",out:"0\n0"},{in:"4\n5 5 5 5\n5 5",out:"4\n20"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    int a, b;\n    cin >> a >> b;\n    long long tong = 0;\n    // count_if(..., [a, b](int x) { ... })\n    // for_each(..., [&tong, a, b](int x) { ... })\n    return 0;\n}",need:/count_if[\s\S]*\[[^\]]*\][\s\S]*for_each[\s\S]*\[[^\]]*&/,needMsg:"Hãy dùng count_if với lambda, và for_each với lambda bắt tổng theo tham chiếu."},{t:"Máy tính chọn phép",d:"Nhập q, rồi q dòng dạng <code>a op b<\/code> với op là một trong <code>+ - * m<\/code> (m: số lớn hơn). In kết quả mỗi dòng. Dùng một <code>map&lt;char, function&lt;long long(long long, long long)&gt;&gt;<\/code> ánh xạ mỗi ký tự phép toán sang một lambda, rồi chỉ cần một lời gọi <code>bang[op](a, b)<\/code>.",tests:[{in:"4\n3 + 4\n10 - 7\n6 * 7\n2 m 9",out:"7\n3\n42\n9"},{in:"1\n1000000 * 1000000",out:"1000000000000"},{in:"2\n-5 m -8\n0 - 5",out:"-5\n-5"}],start:"#include <iostream>\n#include <map>\n#include <functional>\nusing namespace std;\n\nint main() {\n    map<char, function<long long(long long, long long)>> bang;\n    // bang['+'] = [](long long a, long long b) { return a + b; };\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        long long a, b;\n        char op;\n        cin >> a >> op >> b;\n        // cout << bang[op](a, b) << \"\\n\";\n    }\n    return 0;\n}",need:/function\s*<[\s\S]*\[\s*\]\s*\(/,needMsg:"Hãy lưu các lambda vào map của std::function."}]);

makeQuiz("quiz42","score42",[{"q": "<code>int k = 1; auto f = [k]() { return k; }; k = 5;<\/code> Khi đó <code>f()<\/code> trả về:", "o": ["1", "5", "Lỗi biên dịch", "Không xác định"], "a": 0, "e": "[k] chép giá trị của k lúc tạo lambda (1); sửa k sau đó không ảnh hưởng bản chép."}, {"q": "Muốn lambda cộng dồn vào biến <code>tong<\/code> của main, phải bắt thế nào?", "o": ["[tong]", "[=]", "[&tong]", "[] rồi khai báo tong trong lambda"], "a": 2, "e": "Bắt theo tham chiếu để lambda sửa chính biến tong; [tong] chỉ có bản chép (và bản chép là hằng)."}, {"q": "<code>[dem]() mutable { return ++dem; }<\/code> được gọi 3 lần, biến <code>dem<\/code> của main (ban đầu 0) là:", "o": ["3", "0", "1", "Lỗi biên dịch"], "a": 1, "e": "mutable cho phép sửa bản chép bên trong lambda; biến dem của main không bị đụng tới."}, {"q": "Kiểu nào giữ được cả hàm <code>int f(int)<\/code> lẫn lambda <code>[k](int x) { return x + k; }<\/code>?", "o": ["auto", "int(*)(int)", "function&lt;int(int)&gt;", "void*"], "a": 2, "e": "std::function giữ mọi thứ gọi được có cùng dạng. Con trỏ hàm không giữ được lambda có bắt biến; auto chỉ là suy kiểu từ giá trị khởi tạo."}]);

